begin;
create table public.integracao_revisoes(modulo text primary key,versao bigint not null default 0);
alter table public.integracao_revisoes enable row level security;
revoke all on public.integracao_revisoes from public,anon,authenticated;
grant select on public.integracao_revisoes to authenticated;
create policy revisoes_ler on public.integracao_revisoes for select to authenticated using(exists(select 1 from public.profiles where id=auth.uid() and ativo));
create function integracao_crm_privado.sinalizar_revisao() returns trigger language plpgsql security definer set search_path='' as $$begin
 update public.integracao_revisoes set versao=versao+1 where modulo=tg_argv[0];return null;
end $$;
revoke all on function integracao_crm_privado.sinalizar_revisao() from public,anon,authenticated;
insert into public.integracao_revisoes(modulo) values('clientes');
do $$begin if to_regclass('public.fin_receb_municipios') is not null then execute 'create trigger integracao_revisao after insert or update or delete on public.fin_receb_municipios for each statement execute function integracao_crm_privado.sinalizar_revisao(''clientes'')';end if;end $$;
